// @generated by:gauntlet run:godseye-local-backend
import { randomUUID } from "node:crypto";
import { describe, expect, it } from "vitest";
import { APP_API_HEADER, APP_API_VERSION } from "../packages/app-backend/src/index.js";
import { createGodseyeClient, parseApplicationEvents } from "../packages/sdk/src/index.js";

const baseUrl = "http://localhost:4731";
const scope = { projectId: randomUUID(), environmentId: randomUUID() };
const reply = (value: unknown, headers: HeadersInit = {}) =>
  Response.json(value, {
    headers: { [APP_API_HEADER]: APP_API_VERSION, ...Object.fromEntries(new Headers(headers)) },
  });
function eventResponse(chunks: Uint8Array[]) {
  return new Response(
    new ReadableStream<Uint8Array>({
      start(controller) {
        for (const chunk of chunks) controller.enqueue(chunk);
        controller.close();
      },
    }),
    { headers: { "content-type": "text/event-stream" } },
  );
}
async function parse(response: Response) {
  const messages = [];
  for await (const message of parseApplicationEvents(response, new AbortController().signal))
    messages.push(message);
  return messages;
}

describe("application SDK response and incremental-event contract", () => {
  it("T-AC-60 rejects unsupported API versions before trusting JSON", async () => {
    const client = createGodseyeClient({
      baseUrl,
      scope,
      fetch: async () => reply(null, { [APP_API_HEADER]: "999.0.0" }),
    });
    await expect(client.auth.session()).rejects.toMatchObject({ code: "UNSUPPORTED_VERSION" });
  });

  it("T-AC-60 rejects malformed successful API DTOs instead of silently widening types", async () => {
    const client = createGodseyeClient({
      baseUrl,
      scope,
      fetch: async () => reply({ user: { id: "fake" }, session: {} }),
    });
    await expect(client.auth.session()).rejects.toMatchObject({ code: "INVALID_RESPONSE" });
  });

  it("T-AC-60 bounds response bytes and never includes upstream private bodies in thrown errors", async () => {
    const marker = "synthetic-private-response-marker";
    const client = createGodseyeClient({
      baseUrl,
      scope,
      fetch: async () =>
        new Response(marker.repeat(20000), { headers: { [APP_API_HEADER]: APP_API_VERSION } }),
    });
    await expect(client.auth.session()).rejects.toMatchObject({ code: "RESPONSE_TOO_LARGE" });
    try {
      await client.auth.session();
    } catch (error) {
      expect(String(error)).not.toContain(marker);
    }
  });

  it("T-AC-60 parses UTF-8 domain frames fragmented at every single byte boundary", async () => {
    const event = {
      id: "1",
      type: "document.updated",
      payload: { title: "Étoile 🛰️" },
      occurredAt: new Date().toISOString(),
    };
    const cursor = `v1.1.${"a".repeat(43)}`;
    const bytes = new TextEncoder().encode(
      `id: ${cursor}\nevent: domain\ndata: ${JSON.stringify(event)}\n\n`,
    );
    const chunks = [...bytes].map((byte) => new Uint8Array([byte]));
    expect(await parse(eventResponse(chunks))).toEqual([{ kind: "event", cursor, event }]);
  });

  it("T-AC-60 parses CRLF boundaries even when each carriage return and newline arrive separately", async () => {
    const bytes = new TextEncoder().encode(
      'event: refetch\r\ndata: {"reason":"cursor_gap"}\r\n\r\n',
    );
    expect(await parse(eventResponse([...bytes].map((byte) => new Uint8Array([byte]))))).toEqual([
      { kind: "refetch", reason: "cursor_gap" },
    ]);
  });

  it("T-AC-60 rejects malformed domain payloads and forged cursor shapes", async () => {
    const invalid = new TextEncoder().encode('id: foreign\nevent: domain\ndata: {"id":"1"}\n\n');
    await expect(parse(eventResponse([invalid]))).rejects.toMatchObject({
      code: "INVALID_EVENT_CURSOR",
    });
    const invalidJson = new TextEncoder().encode("event: domain\ndata: {\n\n");
    await expect(parse(eventResponse([invalidJson]))).rejects.toMatchObject({
      code: "INVALID_EVENT_STREAM",
    });
  });

  it("T-AC-60 bounds unterminated event frames instead of buffering indefinitely", async () => {
    await expect(
      parse(eventResponse([new TextEncoder().encode(`data: ${"x".repeat(131073)}`)])),
    ).rejects.toMatchObject({ code: "EVENT_FRAME_TOO_LARGE" });
  });

  it("T-AC-60 cancels an idle source promptly when its AbortSignal is revoked", async () => {
    let cancelled = false;
    const abort = new AbortController();
    const response = new Response(
      new ReadableStream<Uint8Array>({
        cancel() {
          cancelled = true;
        },
      }),
      { headers: { "content-type": "text/event-stream" } },
    );
    const stream = parseApplicationEvents(response, abort.signal);
    const pending = stream.next();
    abort.abort();
    expect((await pending).done).toBe(true);
    expect(cancelled).toBe(true);
  });
});
